css:
.lk-stage, .wt-stage { border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.lk-stage canvas, .wt-stage canvas { touch-action: none; cursor: grab; }
.lk-stage canvas.holding, .wt-stage canvas.holding { cursor: grabbing; }
.lk-out, .wt-out { margin: 0; font-size: 21px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 3.2em; }
.lk-table { width: 100%; border-collapse: collapse; font-size: 18px; }
.lk-table th, .lk-table td { border: 1.5px solid var(--rule); padding: 3px 8px; text-align: center; }
.lk-table thead th { background: color-mix(in srgb, var(--accent) 12%, #fff); }

